 $cards=[['Total users',(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn()],['Students',$roleCount('student')],['Active supervisors',$roleCount('supervisor'," AND u.account_status='active'")],['HODs',$roleCount('coordinator'," AND u.account_status='active'")],['Deans',$roleCount('dean'," AND u.account_status='active'")],['Examiners',$roleCount('examiner'," AND u.account_status='active'")],['Active projects',(int)db()->query("SELECT COUNT(*) FROM projects WHERE status NOT IN ('completed','archived')")->fetchColumn()],['Completed projects',(int)db()->query("SELECT COUNT(*) FROM projects WHERE status IN ('completed','archived')")->fetchColumn()],['Pending academic reviews',$pendingReviews]];
