 $q=db()->prepare("SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE u.department_id=? AND r.name='student'");$q->execute([$departmentId]);$studentCount=(int)$q->fetchColumn();
 $q=db()->prepare("SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE u.department_id=? AND r.name='supervisor' AND u.account_status='active'");$q->execute([$departmentId]);$supervisorCount=(int)$q->fetchColumn();
 $q=db()->prepare("SELECT COUNT(*) FROM users st JOIN roles r ON r.id=st.role_id WHERE st.department_id=? AND r.name='student' AND NOT EXISTS (SELECT 1 FROM student_supervisors ss WHERE ss.student_id=st.id AND ss.ended_at IS NULL)");$q->execute([$departmentId]);$unassignedStudents=(int)$q->fetchColumn();
 $cards=[['Department students',$studentCount],['Active supervisors',$supervisorCount],['Active projects',$projectCount("status NOT IN ('completed','archived')")],['Completed projects',$projectCount("status IN ('completed','archived')")],['Students without supervisors',$unassignedStudents],['Projects needing attention',$projectCount("status IN ('idea_submitted','idea_under_review','supervisor_pending','correction_required','under_evaluation')")]];
 $q=db()->prepare('SELECT id,reference_no,title,status,created_at FROM projects WHERE department_id=? ORDER BY created_at DESC LIMIT 8');$q->execute([$departmentId]);$rows=$q->fetchAll();
}elseif($role==='supervisor'){
