 $q=db()->prepare("SELECT COUNT(*) FROM submissions s JOIN project_supervisors ps ON ps.project_id=s.project_id WHERE ps.supervisor_id=? AND ps.ended_at IS NULL AND s.status IN ('submitted','resubmitted','under_review')");$q->execute([$u['id']]);$pendingSubmissions=(int)$q->fetchColumn();
