 $cards=[['Assigned students',$students],['Active projects',$active],['Pending academic reviews',$pending],['Open corrections',$corrections]];
 $q=db()->prepare("SELECT COUNT(DISTINCT p.id) FROM projects p JOIN project_supervisors ps ON ps.project_id=p.id WHERE ps.supervisor_id=? AND ps.ended_at IS NULL AND p.status IN ('approved','completed','archived')");$q->execute([$u['id']]);$cards[]=['Approved projects',(int)$q->fetchColumn()];
 $cards[]=['Idea decisions pending',$pendingIdeas];
 $q=db()->prepare('SELECT DISTINCT p.id,p.reference_no,p.title,p.status,p.updated_at FROM projects p JOIN project_supervisors ps ON ps.project_id=p.id WHERE ps.supervisor_id=? AND ps.ended_at IS NULL ORDER BY p.updated_at DESC LIMIT 8');$q->execute([$u['id']]);$rows=$q->fetchAll();
}elseif($role==='student'){
