 $submissionCount=0;$progress=0;
 if($project){$q=db()->prepare('SELECT COUNT(*) FROM submissions WHERE project_id=?');$q->execute([$project['id']]);$submissionCount=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*),SUM(status='completed') FROM milestones WHERE project_id=?");$q->execute([$project['id']]);[$allMilestones,$doneMilestones]=$q->fetch(PDO::FETCH_NUM);$progress=(int)$allMilestones?round(100*(int)$doneMilestones/(int)$allMilestones):0;}
