 $rows=$project?db()->prepare('SELECT document_type,status,submitted_at FROM submissions WHERE project_id=? ORDER BY submitted_at DESC LIMIT 8'):null;if($rows){$rows->execute([$project['id']]);$rows=$rows->fetchAll();}else{$rows=[];}
