 $q=db()->prepare('SELECT p.id,p.reference_no,p.title,pe.status,pe.evaluation_due_at FROM projects p JOIN project_examiners pe ON pe.project_id=p.id WHERE pe.examiner_id=? AND pe.status<>"withdrawn" ORDER BY pe.evaluation_due_at LIMIT 8');$q->execute([$u['id']]);$rows=$q->fetchAll();
}
