 $q=db()->prepare("SELECT s.id submission_id,p.id project_id,p.reference_no,p.title,s.document_type,s.status,s.submitted_at,st.first_name,st.last_name,st.matric_number FROM submissions s JOIN projects p ON p.id=s.project_id JOIN project_supervisors ps ON ps.project_id=p.id AND ps.ended_at IS NULL JOIN users st ON st.id=s.student_id WHERE ps.supervisor_id=? AND s.status IN ('submitted','resubmitted','under_review') ORDER BY s.submitted_at LIMIT 8");$q->execute([$u['id']]);$supervisorSubmissionQueue=$q->fetchAll();
