$dq=db()->prepare('SELECT d.title,d.milestone_key,d.due_at FROM deadlines d JOIN academic_sessions s ON s.id=d.academic_session_id WHERE s.is_current=1 AND d.due_at BETWEEN DATE_SUB(NOW(),INTERVAL 30 DAY) AND DATE_ADD(NOW(),INTERVAL 60 DAY)'.$deadlineScope.' ORDER BY d.due_at LIMIT 8');$dq->execute($deadlineParams);$deadlineRows=$dq->fetchAll();
