d']:'coordinator/projects.php'))) ?>"><?= $role==='examiner'?'Evaluate':($role==='supervisor'?'Review':'Open') ?></a></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
